import 'package:undo/undo.dart';

void main() {
  final changes = ChangeStack();
  var count = 0;

  changes.add(
    Change<int>(
      count,
      () => count++,
      (oldVal) => count = oldVal,
      description: 'Increment count',
    ),
  );

  changes.undo();
  changes.redo();
}
